contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address caller, address other) public payable {
        require(caller != address(this), "caller must not be the test contract");
        require(other != caller, "other must differ from caller");

        uint256 beforeBalCaller = c.balances(caller); if (__ESBMC_reverted()) return;
        uint256 beforeBalOther = c.balances(other); if (__ESBMC_reverted()) return;
        uint256 beforeReserve = address(c).balance;

        bool reverted;
        c.withdraw(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterBalCaller = c.balances(caller); if (__ESBMC_reverted()) return;
        uint256 afterBalOther = c.balances(other); if (__ESBMC_reverted()) return;
        uint256 afterReserve = address(c).balance;

        assert(
            beforeBalCaller == 0
                ? (!reverted && afterBalCaller == 0 && afterReserve == beforeReserve && afterBalOther == beforeBalOther)
                : true
        );
    }

    receive() external payable {}
}

